# Surah At-Talaq (chapter 65) — all ayat 1-12 (IDs 5218-5229)
SURAH = 65

ENTRIES = {
5218: (
"بسم اللہ الرّحْمٰن الرّحِیْم — اے نبی جب تم عورتوں کو طلاق دو تو ان کی عدت کے مطابق طلاق دو اور عدت کا حساب رکھو — اور اپنے رب اللہ سے ڈرو — انہیں ان کے گھروں سے نہ نکالو اور نہ وہ نکلیں الا یہ کہ وہ کھلی بے حیائی کریں — اور یہ اللہ کی حدیں ہیں — اور جو اللہ کی حدوں سے تجاوز کرے اس نے اپنے آپ پر ظلم کیا — تم نہیں جانتے شاید اللہ اس کے بعد کوئی بات پیدا کر دے",
"""۱۔ طلاق اور عدت — یا أیها النبی إذا طلقتم النساء فطلّقوهن لعدّتهن و أحصوا العدة؛ و اتقوا الله ربکم؛ لا تخرجوهن من بیوتهن و لا یخرجن إلا أن یأتین بفاحشة مبینۃ؛ و تلک حدود الله؛ و من یتعدّ حدود الله فقد ظلم نفسه؛ لا تدري لعل الله یحدث بعد ذلک أمرًا۔
۲۔ ’’يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا الْعِدَّۃَ وَاتَّقُوا اللَّهَ رَبَّكُمْ لَا تُخْرِجُوهُنَّ مِن بُيُوتِهِنَّ وَلَا يَخْرُجْنَ إِلَّا أَن يَأْتِينَ بِفَاحِشَۃٍ مُّبَيِّنَۃٍ وَتِلْكَ حُدُودُ اللَّهِ وَمَن يَتَعَدَّ حُدُودَ اللَّهِ فَقَدْ ظَلَمَ نَفْسَهُ لَا تَدْرِي لَعَلَّ اللَّهَ يُحْدِثُ بَعْدَ ذَٰلِكَ أَمْرًا‘‘ — اے نبی جب تم عورتوں کو طلاق دو تو ان کی عدت کے مطابق طلاق دو اور عدت کا حساب رکھو — اور اپنے رب اللہ سے ڈرو — انہیں ان کے گھروں سے نہ نکالو اور نہ وہ نکلیں الا یہ کہ وہ کھلی بے حیائی کریں — اور یہ اللہ کی حدیں ہیں — اور جو اللہ کی حدوں سے تجاوز کرے اس نے اپنے آپ پر ظلم کیا — تم نہیں جانتے شاید اللہ اس کے بعد کوئی بات پیدا کر دے — یعنی اے نبی جب تم عورتوں کو طلاق دو تو ان کی عدت کے مطابق طلاق دو اور عدت کا حساب رکھو اور اپنے رب اللہ سے ڈرو انہیں ان کے گھروں سے نہ نکالو اور نہ وہ نکلیں الا یہ کہ وہ کھلی بے حیائی کریں اور یہ اللہ کی حدیں ہیں اور جو اللہ کی حدوں سے تجاوز کرے اس نے اپنے آپ پر ظلم کیا تم نہیں جانتے شاید اللہ اس کے بعد کوئی بات پیدا کر دے۔
۳۔ عملی سبق: اللہ کی حدود کی پامالی نہ کرو؛ اللہ سے ڈرو۔"""
),
5219: (
"پھر جب وہ اپنی مدت تک پہنچیں تو انہیں بھلائی کے ساتھ روک لو یا بھلائی کے ساتھ ان سے الگ ہو جاؤ — اور اپنے میں سے دو عادل گواہ بناؤ — اور اللہ کے لیے شہادت قائم کرو — یہ نصیحت اسے کی جاتی ہے جو اللہ اور آخرت کے دن پر ایمان رکھتا ہو — اور جو اللہ سے ڈرے اس کے لیے اللہ راستہ بنا دے گا",
"""۱۔ عدت کے اختتام پر — فإذا بلغن أجلهن فأمسکوهن بمعروف أو فارقوهن بمعروف و أشهدوا ذوَي عدل منکم و أقیموا الشهادۃ لله; ذلکم یُوعظ به من کان یؤمن بالله و الیوم الآخر; و من یتّق الله یجعل له مخرجًا۔
۲۔ ’’فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ فَارِقُوهُنَّ بِمَعْرُوفٍ وَأَشْهِدُوا ذَوَيْ عَدْلٍ مِّنكُمْ وَأَقِيمُوا الشَّهَادَۃَ لِلَّهِ ذَٰلِكُمْ يُوعَظُ بِهِ مَن كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَمَن يَتَّقِ اللَّهَ يَجْعَل لَّهُ مَخْرَجًا‘‘ — پھر جب وہ اپنی مدت تک پہنچیں تو انہیں بھلائی کے ساتھ روک لو یا بھلائی کے ساتھ ان سے الگ ہو جاؤ — اور اپنے میں سے دو عادل گواہ بناؤ — اور اللہ کے لیے شہادت قائم کرو — یہ نصیحت اسے کی جاتی ہے جو اللہ اور آخرت کے دن پر ایمان رکھتا ہو — اور جو اللہ سے ڈرے اس کے لیے اللہ راستہ بنا دے گا — یعنی پھر جب وہ اپنی مدت تک پہنچیں تو انہیں بھلائی کے ساتھ روک لو یا بھلائی کے ساتھ ان سے الگ ہو جاؤ اور اپنے میں سے دو عادل گواہ بناؤ اور اللہ کے لیے شہادت قائم کرو یہ نصیحت اسے کی جاتی ہے جو اللہ اور آخرت کے دن پر ایمان رکھتا ہو اور جو اللہ سے ڈرے اس کے لیے اللہ راستہ بنا دے گا۔
۳۔ عملی سبق: اللہ سے ڈرو؛ اللہ راستہ بنا دے گا۔"""
),
5220: (
"اور اسے وہاں سے رزق دے جہاں سے اس کا گمان بھی نہ ہو — اور جو اللہ پر توکل کرے وہ اس کے لیے کافی ہے — بے شک اللہ اپنا کام پورا کر کے رہتا ہے — اللہ نے ہر چیز کے لیے مقدار مقرر کر دی ہے",
"""۱۔ رزقِ بے حساب — و یرزقه من حیث لا یحتسب; و من یتوکل علی الله فهو حسبه; إن الله بالغ أمره; قد جعل الله لکل شيء قدرًا۔
۲۔ ’’وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ وَمَن يَتَوَكَّلْ عَلَى اللَّهِ فَهُوَ حَسْبُهُ إِنَّ اللَّهَ بَالِغُ أَمْرِهِ قَدْ جَعَلَ اللَّهُ لِكُلِّ شَيْءٍ قَدْرًا‘‘ — اور اسے وہاں سے رزق دے جہاں سے اس کا گمان بھی نہ ہو — اور جو اللہ پر توکل کرے وہ اس کے لیے کافی ہے — بے شک اللہ اپنا کام پورا کر کے رہتا ہے — اللہ نے ہر چیز کے لیے مقدار مقرر کر دی ہے — یعنی اور اسے وہاں سے رزق دے جہاں سے اس کا گمان بھی نہ ہو اور جو اللہ پر توکل کرے وہ اس کے لیے کافی ہے بے شک اللہ اپنا کام پورا کر کے رہتا ہے اللہ نے ہر چیز کے لیے مقدار مقرر کر دی ہے۔
۳۔ عملی سبق: اللہ پر توکل کرو؛ اللہ سے ڈرو۔"""
),
5221: (
"اور جو تمہاری عورتوں میں حیض سے ناامید ہو چکی ہوں اگر تمہیں شبہ ہو تو ان کی عدت تین مہینے ہے — اور جن کو ابھی حیض نہیں آیا ان کی بھی — اور حاملہ عورتوں کی عدت ان کے وضع حمل تک ہے — اور جو اللہ سے ڈرے اس کے کام میں آسانی کر دے",
"""۱۔ خاص عدت — و اللائي یئسن من المحیض من نسائکم إن ارتبتم فعدتهن ثلاثۃ أشهر و اللائي لم یحضن; و أولات الأحمال أجلهن أن یضعن حملهن; و من یتّق الله یجعل له من أمره یسرًا۔
۲۔ ’’وَاللَّائِي يَئِسْنَ مِنَ الْمَحِيضِ مِن نِّسَائِكُمْ إِنِ ارْتَبْتُمْ فَعِدَّتُهُنَّ ثَلَاثَۃُ أَشْهُرٍ وَاللَّائِي لَمْ يَحِضْنَ وَأُولَاتُ الْأَحْمَالِ أَجَلُهُنَّ أَن يَضَعْنَ حَمْلَهُنَّ وَمَن يَتَّقِ اللَّهَ يَجْعَل لَّهُ مِنْ أَمْرِهِ يُسْرًا‘‘ — اور جو تمہاری عورتوں میں حیض سے ناامید ہو چکی ہوں اگر تمہیں شبہ ہو تو ان کی عدت تین مہینے ہے — اور جن کو ابھی حیض نہیں آیا ان کی بھی — اور حاملہ عورتوں کی عدت ان کے وضع حمل تک ہے — اور جو اللہ سے ڈرے اس کے کام میں آسانی کر دے — یعنی اور جو تمہاری عورتوں میں حیض سے ناامید ہو چکی ہوں اگر تمہیں شبہ ہو تو ان کی عدت تین مہینے ہے اور جن کو ابھی حیض نہیں آیا ان کی بھی اور حاملہ عورتوں کی عدت ان کے وضع حمل تک ہے اور جو اللہ سے ڈرے اس کے کام میں آسانی کر دے۔
۳۔ عملی سبق: اللہ سے ڈرو؛ آسانی ملے گی؛ اللہ سے ڈرو۔"""
),
5222: (
"یہ اللہ کا حکم ہے جو اس نے تم پر نازل کیا — اور جو اللہ سے ڈرے وہ اس کے گناہ معاف کر دے اور اس کا اجر بڑھا دے",
"""۱۔ اللہ کا حکم — ذلک أمر الله أنزله إلیكم؛ و من یتّق الله یکفّر عنه سیئاته و یُعظم له أجرا۔
۲۔ ’’ذَٰلِكَ أَمْرُ اللَّهِ أَنزَلَهُ إِلَيْكُمْ وَمَن يَتَّقِ اللَّهَ يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُعْظِمْ لَهُ أَجْرًا‘‘ — یہ اللہ کا حکم ہے جو اس نے تم پر نازل کیا — اور جو اللہ سے ڈرے وہ اس کے گناہ معاف کر دے اور اس کا اجر بڑھا دے — یعنی یہ اللہ کا حکم ہے جو اس نے تم پر نازل کیا اور جو اللہ سے ڈرے وہ اس کے گناہ معاف کر دے اور اس کا اجر بڑھا دے۔
۳۔ عملی سبق: اللہ کے احکام پر عمل کرو؛ اللہ سے ڈرو۔"""
),
5223: (
"انہیں اپنی حیثیت کے مطابق جہاں تم رہتے ہو وہیں ٹھکاؤ دو — اور انہیں تنگی میں ڈالنے کے لیے انہیں تکلیف نہ دو — اور اگر وہ حاملہ ہوں تو ان پر خرچ کرو یہاں تک کہ وہ وضع حمل کر دیں — پھر اگر وہ تمہارے لیے دودھ پلائیں تو انہیں ان کی مزدوری دو — اور آپس میں بھلائی کے ساتھ مشورہ کرو — اور اگر تم آپس میں مشکل ڈالو تو دوسری عورت اس بچے کو دودھ پلا دے گی",
"""۱۔ طلاق والی عورتوں کا ٹھکانہ — أسکنوهن من حیث سکنتم من وجدکم و لا تضارّوهن لتضیّقوا علیهن; و إن کُنّ أولات حمل فأنفقوا علیهن حتی یضعن حملهن; فإن أرضعن لکم فآتوهن أجورهن; و أتمروا بینکم بمعروف; و إن تعاسرتم فسترضع له أخری۔
۲۔ ’’أَسْكِنُوهُنَّ مِنْ حَيْثُ سَكَنتُم مِّن وُجْدِكُمْ وَلَا تُضَارُّوهُنَّ لِتُضَيِّقُوا عَلَيْهِنَّ وَإِن كُنَّ أُولَاتِ حَمْلٍ فَأَنفِقُوا عَلَيْهِنَّ حَتَّىٰ يَضَعْنَ حَمْلَهُنَّ فَإِنْ أَرْضَعْنَ لَكُمْ فَآتُوهُنَّ أُجُورَهُنَّ وَأْتَمِرُوا بَيْنَكُم بِمَعْرُوفٍ وَإِن تَعَاسَرْتُمْ فَسَتُرْضِعُ لَهُ أُخْرَىٰ‘‘ — انہیں اپنی حیثیت کے مطابق جہاں تم رہتے ہو وہیں ٹھکاؤ دو — اور انہیں تنگی میں ڈالنے کے لیے انہیں تکلیف نہ دو — اور اگر وہ حاملہ ہوں تو ان پر خرچ کرو یہاں تک کہ وہ وضع حمل کر دیں — پھر اگر وہ تمہارے لیے دودھ پلائیں تو انہیں ان کی مزدوری دو — اور آپس میں بھلائی کے ساتھ مشورہ کرو — اور اگر تم آپس میں مشکل ڈالو تو دوسری عورت اس بچے کو دودھ پلا دے گی — یعنی انہیں اپنی حیثیت کے مطابق جہاں تم رہتے ہو وہیں ٹھکاؤ دو اور انہیں تنگی میں ڈالنے کے لیے انہیں تکلیف نہ دو اور اگر وہ حاملہ ہوں تو ان پر خرچ کرو یہاں تک کہ وہ وضع حمل کر دیں پھر اگر وہ تمہارے لیے دودھ پلائیں تو انہیں ان کی مزدوری دو اور آپس میں بھلائی کے ساتھ مشورہ کرو اور اگر تم آپس میں مشکل ڈالو تو دوسری عورت اس بچے کو دودھ پلا دے گی۔
۳۔ عملی سبق: طلاق دی عورتوں کے حقوق ادا کرو؛ اللہ سے ڈرو۔"""
),
5224: (
"کشادہ دستی والا اپنی خوشحالی میں سے خرچ کرے — اور جس کا رزق تنگ ہو وہ اس میں سے خرچ کرے جو اللہ نے اسے دیا ہے — اللہ کسی جان کو اس سے زیادہ کا مکلف نہیں کرتا جو اسے دیا ہے — اللہ عنقریب تنگی کے بعد آسانی کر دے گا",
"""۱۔ رزق کے مطابق خرچ — لِینفق ذو سعة من سعته; و من قُدِر علیه رزقه فلیُنفق مما آتاه الله; لا یکلّف الله نفسًا إلا ما آتاها; سیجعل الله بعد عسر یسرًا۔
۲۔ ’’لِّيُنفِقْ ذُو سَعَۃٍ مِّن سَعَتِهِ وَمَن قُدِرَ عَلَيْهِ رِزْقُهُ فَلْيُنفِقْ مِمَّا آتَاهُ اللَّهُ لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا مَا آتَاهَا سَيَجْعَلُ اللَّهُ بَعْدَ عُسْرٍ يُسْرًا‘‘ — کشادہ دستی والا اپنی خوشحالی میں سے خرچ کرے — اور جس کا رزق تنگ ہو وہ اس میں سے خرچ کرے جو اللہ نے اسے دیا ہے — اللہ کسی جان کو اس سے زیادہ کا مکلف نہیں کرتا جو اسے دیا ہے — اللہ عنقریب تنگی کے بعد آسانی کر دے گا — یعنی کشادہ دستی والا اپنی خوشحالی میں سے خرچ کرے اور جس کا رزق تنگ ہو وہ اس میں سے خرچ کرے جو اللہ نے اسے دیا ہے اللہ کسی جان کو اس سے زیادہ کا مکلف نہیں کرتا جو اسے دیا ہے اللہ عنقریب تنگی کے بعد آسانی کر دے گا۔
۳۔ عملی سبق: اپنی حیثیت کے مطابق خرچ کرو؛ اللہ سے ڈرو۔"""
),
5225: (
"اور کتنی بستیاں تھیں جنہوں نے اپنے رب اور اس کے رسولوں کے حکم سے سرکشی کی تو ہم نے ان کا سخت حساب کیا اور انہیں سخت عذاب دیا",
"""۱۔ سرکش بستیاں — و کأیّن من قریۃ عَتَت عن أمر ربها و رسله فحاسبناها حسابًا شدیدًا و عذبناها عذابًا نُکرًا۔
۲۔ ’’وَكَأَيِّن مِّن قَرْيَۃٍ عَتَتْ عَنْ أَمْرِ رَبِّهَا وَرُسُلِهِ فَحَاسَبْنَاهَا حِسَابًا شَدِيدًا وَعَذَّبْنَاهَا عَذَابًا نُّكْرًا‘‘ —اور کتنی بستیاں تھیں جنہوں نے اپنے رب اور اس کے رسولوں کے حکم سے سرکشی کی تو ہم نے ان کا سخت حساب کیا اور انہیں سخت عذاب دیا۔
۳۔ عملی سبق: سرکشی نہ کرو؛ اللہ سے ڈرو۔"""
),
5226: (
"پھر انہوں نے اپنے کام کا برا انجام چکھا — اور ان کا انجام خسارا تھا",
"""۱۔ انجام — فذاقت وبال أمرها و کان عاقبۃ أمرها خُسرًا۔
۲۔ ’’فَذَاقَتْ وَبَالَ أَمْرِهَا وَكَانَ عَاقِبَۃُ أَمْرِهَا خُسْرًا‘‘ — پھر انہوں نے اپنے کام کا برا انجام چکھا — اور ان کا انجام خسارا تھا — یعنی پھر انہوں نے اپنے کام کا برا انجام چکھا اور ان کا انجام خسارا تھا۔
۳۔ عملی سبق: گناہ چھوڑو؛ اللہ سے ڈرو۔"""
),
5227: (
"اللہ نے ان کے لیے سخت عذاب تیار کر رکھا ہے — پس اے عقلمندو جو ایمان لائے اللہ سے ڈرو — اللہ نے تم پر نصیحت نازل کی ہے",
"""۱۔ عذابِ آخرت — أعدّ الله لهم عذابًا شدیدًا; فاتقوا الله یا أولي الألباب الذین آمنوا; قد أنزل الله إلیكم ذکرًا۔
۲۔ ’’أَعَدَّ اللَّهُ لَهُمْ عَذَابًا شَدِيدًا فَاتَّقُوا اللَّهَ يَا أُولِي الْأَلْبَابِ الَّذِينَ آمَنُوا قَدْ أَنزَلَ اللَّهُ إِلَيْكُمْ ذِكْرًا‘‘ — اللہ نے ان کے لیے سخت عذاب تیار کر رکھا ہے — پس اے عقلمندو جو ایمان لائے اللہ سے ڈرو — اللہ نے تم پر نصیحت نازل کی ہے — یعنی اللہ نے ان کے لیے سخت عذاب تیار کر رکھا ہے پس اے عقلمندو جو ایمان لائے اللہ سے ڈرو اللہ نے تم پر نصیحت نازل کی ہے۔
۳۔ عملی سبق: عقلمندو اللہ سے ڈرتے رہو؛ خوفِ خدا اختیار کرو۔"""
),
5228: (
"ایک رسول جو تمہیں اللہ کی کھلی آیات پڑھ کر سناتا ہے تاکہ انہیں جو ایمان لائے اور نیک عمل کیے اندھیروں سے روشنی کی طرف نکالے — اور جو اللہ پر ایمان لائے اور نیک عمل کرے اسے ایسی جنتوں میں داخل کرے جن کے نیچے نہریں بہتی ہیں — ہمیشہ ان میں رہیں گے — اللہ نے اس کے رزق کو بہترین بنایا ہے",
"""۱۔ رسول کی بعثت — رسولا یتلو علیکم آیات الله مبینات لیخرج الذین آمنوا و عملوا الصالحات من الظلمات إلی النور; و من یؤمن بالله و یعمل صالحًا یدخله جنات تجري من تحتها الأنهار خالدین فیها أبدا; قد أحسن الله له رزقًا۔
۲۔ ’’رَّسُولًا يَتْلُو عَلَيْكُمْ آيَاتِ اللَّهِ مُبَيِّنَاتٍ لِّيُخْرِجَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ مِنَ الظُّلُمَاتِ إِلَى النُّورِ وَمَن يُؤْمِن بِاللَّهِ وَيَعْمَلْ صَالِحًا يُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا قَدْ أَحْسَنَ اللَّهُ لَهُ رِزْقًا‘‘ — ایک رسول جو تمہیں اللہ کی کھلی آیات پڑھ کر سناتا ہے تاکہ انہیں جو ایمان لائے اور نیک عمل کیے اندھیروں سے روشنی کی طرف نکالے — اور جو اللہ پر ایمان لائے اور نیک عمل کرے اسے ایسی جنتوں میں داخل کرے جن کے نیچے نہریں بہتی ہیں — ہمیشہ ان میں رہیں گے — اللہ نے اس کے رزق کو بہترین بنایا ہے — یعنی ایک رسول جو تمہیں اللہ کی کھلی آیات پڑھ کر سناتا ہے تاکہ انہیں جو ایمان لائے اور نیک عمل کیے اندھیروں سے روشنی کی طرف نکالے اور جو اللہ پر ایمان لائے اور نیک عمل کرے اسے ایسی جنتوں میں داخل کرے جن کے نیچے نہریں بہتی ہیں ہمیشہ ان میں رہیں گے اللہ نے اس کے رزق کو بہترین بنایا ہے۔
۳۔ عملی سبق: اللہ پر ایمان لاؤ اور نیک عمل کرو؛ اللہ سے ڈرو۔"""
),
5229: (
"اللہ وہ ہے جس نے سات آسمان بنائے اور زمین سے بھی اسی کی مثل — حکم ان کے درمیان اترتا ہے تاکہ تم جان لو کہ اللہ ہر چیز پر قادر ہے اور اللہ نے ہر چیز کو اپنے علم سے گھیر لیا ہے",
"""۱۔ سات آسمان — الله الذي خلق سبع سماوات و من الأرض مثلهن یت— نزّل الأمر بینهنّ لتعلمو أن الله علی کل شيء قدیر و أن الله قد أحاط بکل شيء علمًا۔
۲۔ ’’اللَّهُ الَّذِي خَلَقَ سَبْعَ سَمَاوَاتٍ وَمِنَ الْأَرْضِ مِثْلَهُنَّ يَتَنَزَّلُ الْأَمْرُ بَيْنَهُنَّ لِتَعْلَمُوا أَنَّ اللَّهَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ وَأَنَّ اللَّهَ قَدْ أَحَاطَ بِكُلِّ شَيْءٍ عِلْمًا‘‘ — اللہ وہ ہے جس نے سات آسمان بنائے اور زمین سے بھی اسی کی مثل — حکم ان کے درمیان اترتا ہے تاکہ تم جان لو کہ اللہ ہر چیز پر قادر ہے اور اللہ نے ہر چیز کو اپنے علم سے گھیر لیا ہے — یعنی اللہ وہ ہے جس نے سات آسمان بنائے اور زمین سے بھی اسی کی مثل حکم ان کے درمیان اترتا ہے تاکہ تم جان لو کہ اللہ ہر چیز پر قادر ہے اور اللہ نے ہر چیز کو اپنے علم سے گھیر لیا ہے۔
۳۔ عملی سبق: اللہ کی قدرت اور علم پر یقین رکھو؛ اللہ سے ڈرو۔"""
),
}
